    if frontmatter:
        body = "---\nname: %s\ndescription: test skill\n---\n" % path.name
    else:
        body = "---\ndescription: missing name\n---\n"
    if bom:
        body = "﻿" + body
    (path / "SKILL.md").write_text(body, encoding="utf-8")
